contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 dep) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (dep)); require(dep <= 1000000000000000000000000000000);
        require(address(this).balance >= dep);
        require(dep > 0);

        uint256 beforeC = address(c).balance;
        uint256 callerBefore = address(this).balance;

        c.deposit{value: dep}(); if (__ESBMC_reverted()) return;

        uint256 afterC = address(c).balance;
        uint256 callerAfterDep = address(this).balance;

        bool reverted;
        c.refund(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint256 finalC = address(c).balance;
        uint256 finalCaller = address(this).balance;

        assert(
            reverted
                ? (finalC == afterC && finalCaller == callerAfterDep)
                : (finalC == beforeC && finalCaller == callerBefore)
        );
    }

    receive() external payable {}
}

