// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 dep) internal {
        dep = bound(dep, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= dep);
        vm.assume(dep > 0);
        uint256 beforeC = address(c).balance;
        uint256 callerBefore = address(this).balance;
        try c.deposit{value: dep}() {} catch { return; }
        uint256 afterC = address(c).balance;
        uint256 callerAfterDep = address(this).balance;
        bool reverted;
        try c.refund() { reverted = false; } catch { reverted = true; }
        uint256 finalC = address(c).balance;
        uint256 finalCaller = address(this).balance;
        assertTrue(reverted
                ? (finalC == afterC && finalCaller == callerAfterDep)
                : (finalC == beforeC && finalCaller == callerBefore));
    }

    function testFuzz_run(uint256 dep) public {
        _run(dep);
    }

    receive() external payable {}
}
